import type { ActivityLevel, GoalType } from '../types';

const activityMultipliers: Record<ActivityLevel, number> = {
  'sedentary': 1.2,
  'light': 1.375,
  'moderate': 1.55,
  'active': 1.725,
  'very-active': 1.9,
};

export function calculateBMR(weight: number, height: number, age: number, gender: 'male' | 'female'): number {
  if (gender === 'male') {
    return Math.round(88.362 + (13.397 * weight) + (4.799 * height) - (5.677 * age));
  }
  return Math.round(447.593 + (9.247 * weight) + (3.098 * height) - (4.330 * age));
}

export function calculateTDEE(bmr: number, activityLevel: ActivityLevel): number {
  return Math.round(bmr * activityMultipliers[activityLevel]);
}

export function calculateGoalCalories(
  tdee: number,
  goal: GoalType,
  intensity: 'mild' | 'moderate' | 'aggressive' = 'moderate'
): number {
  const adjustments = {
    mild: 250,
    moderate: 500,
    aggressive: 750,
  };

  const adjustment = adjustments[intensity];

  if (goal === 'lose-weight') {
    return Math.round(tdee - adjustment);
  }
  return Math.round(tdee + adjustment);
}

export function calculateMacros(
  calories: number,
  goal: GoalType,
  _weight: number
): { protein: number; carbs: number; fats: number } {
  let proteinRatio: number;
  let fatRatio: number;

  if (goal === 'lose-weight') {
    proteinRatio = 0.35;
    fatRatio = 0.25;
  } else {
    proteinRatio = 0.30;
    fatRatio = 0.25;
  }

  const carbRatio = 1 - proteinRatio - fatRatio;

  const protein = Math.round((calories * proteinRatio) / 4);
  const fats = Math.round((calories * fatRatio) / 9);
  const carbs = Math.round((calories * carbRatio) / 4);

  return { protein, carbs, fats };
}

export function calculateWeeksToGoal(
  currentWeight: number,
  targetWeight: number,
  weeklyChange: number = 0.5
): number {
  const weightDifference = Math.abs(targetWeight - currentWeight);
  return Math.ceil(weightDifference / weeklyChange);
}

export function getIdealWeightRange(height: number, _gender: 'male' | 'female'): { min: number; max: number } {
  const heightInMeters = height / 100;
  const minBMI = 18.5;
  const maxBMI = 24.9;

  return {
    min: Math.round(minBMI * heightInMeters * heightInMeters),
    max: Math.round(maxBMI * heightInMeters * heightInMeters),
  };
}

export function calculateBMI(weight: number, height: number): number {
  const heightInMeters = height / 100;
  return Math.round((weight / (heightInMeters * heightInMeters)) * 10) / 10;
}

export function getBMICategory(bmi: number): string {
  if (bmi < 18.5) return 'Underweight';
  if (bmi < 25) return 'Normal';
  if (bmi < 30) return 'Overweight';
  return 'Obese';
}

import { motion } from 'framer-motion';
import type { ReactNode } from 'react';

interface FitnessButtonProps {
  children: ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  className?: string;
  disabled?: boolean;
  type?: 'button' | 'submit';
  fullWidth?: boolean;
  'data-testid'?: string;
}

export function FitnessButton({
  children,
  onClick,
  variant = 'primary',
  size = 'md',
  className = '',
  disabled = false,
  type = 'button',
  fullWidth = false,
  'data-testid': testId,
}: FitnessButtonProps) {
  const baseClasses = 'font-semibold rounded-xl transition-all flex items-center justify-center gap-2 relative overflow-hidden';

  const variantClasses = {
    primary: 'bg-gradient-to-r from-purple-500 via-purple-600 to-purple-700 text-white hover:from-purple-600 hover:via-purple-700 hover:to-purple-800 shadow-lg shadow-purple-500/25 hover:shadow-xl hover:shadow-purple-500/40 active:shadow-purple-500/50',
    secondary: 'bg-white/10 text-white hover:bg-white/15 backdrop-blur-sm border border-white/10 hover:border-white/20',
    outline: 'border-2 border-purple-500/50 text-purple-400 hover:bg-purple-500/10 hover:border-purple-400 hover:shadow-lg hover:shadow-purple-500/10',
    ghost: 'text-gray-400 hover:text-white hover:bg-white/5',
  };

  const sizeClasses = {
    sm: 'px-4 py-2 text-sm',
    md: 'px-6 py-3 text-base',
    lg: 'px-8 py-4 text-lg',
  };

  return (
    <motion.button
      type={type}
      onClick={onClick}
      disabled={disabled}
      data-testid={testId}
      className={`${baseClasses} ${variantClasses[variant]} ${sizeClasses[size]} ${fullWidth ? 'w-full' : ''} ${disabled ? 'opacity-50 cursor-not-allowed' : ''} ${className}`}
      whileHover={!disabled ? { scale: 1.02 } : undefined}
      whileTap={!disabled ? { scale: 0.98 } : undefined}
      transition={{ type: "spring", stiffness: 400, damping: 17 }}
    >
      {variant === 'primary' && (
        <span className="absolute inset-0 overflow-hidden rounded-xl">
          <span className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full hover:translate-x-full transition-transform duration-1000 ease-out group-hover:translate-x-full" />
        </span>
      )}
      <span className="relative z-10 flex items-center justify-center gap-2">{children}</span>
    </motion.button>
