          <Apple className="w-8 h-8 mx-auto mb-2 text-pink-400" />
          <div className="text-3xl font-bold text-white" data-testid="text-fats">{macros.fats}g</div>
          <div className="text-gray-400">Fats</div>
        </FitnessCard>
      </div>

