@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/* Fitness Tracker Specific Styles - Dark Theme Override */
.fitness-app {
  --background: 225 15% 8%;
  --foreground: 0 0% 98%;
  --card: 225 15% 12%;
  --card-foreground: 0 0% 98%;
  --card-border: 225 15% 18%;
  --primary: 271 81% 56%;
  --primary-foreground: 0 0% 100%;
}

/* Container Responsive */
.container-responsive {
  @apply max-w-[1200px] mx-auto px-4 md:px-6 lg:px-8;
}

/* Glass Effect for Dark Theme */
.glass {
  background: rgba(15, 15, 20, 0.85);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

/* Gradient Text */
.gradient-text {
  background: linear-gradient(135deg, #a855f7 0%, #6366f1 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Gradient Border Effect */
.gradient-border {
  position: relative;
  background: rgba(20, 20, 25, 0.9);
  border-radius: 1rem;
}

.gradient-border::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, rgba(168, 85, 247, 0.4), rgba(99, 102, 241, 0.2));
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

/* Card Glow Effect */
.card-glow {
  transition: box-shadow 0.3s ease;
}

.card-glow:hover {
  box-shadow: 0 0 30px rgba(168, 85, 247, 0.15);
}

/* Page Header Layout */
.page-header {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

@media (min-width: 768px) {
  .page-header {
    flex-direction: row;
    align-items: center;
    gap: 1.5rem;
  }
}

/* Typography Scales */
.text-page-title {
  @apply text-3xl md:text-4xl lg:text-5xl font-bold;
}

.text-section-title {
  @apply text-xl md:text-2xl font-bold;
}

.text-card-title {
  @apply text-lg md:text-xl font-semibold;
}

.text-body {
  @apply text-base;
}

.text-label {
  @apply text-sm;
}

/* Activity Level Buttons */
.activity-btn {
  @apply w-full text-left p-4 rounded-xl border border-white/10 transition-all;
}

.activity-btn:hover {
  @apply border-purple-500/30 bg-white/5;
}

.activity-btn.active {
  @apply border-purple-500 bg-purple-500/10;
}

/* Form Inputs for Fitness */
.fitness-input {
  @apply w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white placeholder-gray-500 transition-all;
  @apply focus:border-purple-500 focus:outline-none focus:ring-2 focus:ring-purple-500/20;
}

.fitness-input:focus {
  background: rgba(168, 85, 247, 0.05);
}

/* Gender Buttons */
.gender-btn {
  @apply flex-1 py-4 px-6 rounded-xl border transition-all text-center font-medium;
}

.gender-btn.inactive {
  @apply border-white/10 text-gray-400 hover:border-white/20 hover:bg-white/5;
}

.gender-btn.active-male {
  @apply border-blue-500 bg-blue-500/20 text-blue-400;
}

.gender-btn.active-female {
  @apply border-pink-500 bg-pink-500/20 text-pink-400;
}

/* Hero Gradient */
.hero-gradient {
  background: radial-gradient(ellipse at top, rgba(168, 85, 247, 0.15) 0%, transparent 60%);
}

/* Stat Cards */
.stat-card {
  @apply relative overflow-hidden rounded-2xl p-6 lg:p-8;
  background: rgba(20, 20, 25, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

/* Feature Cards for Landing */
.feature-card {
  @apply h-full p-6 lg:p-8 rounded-2xl flex flex-col;
  background: rgba(20, 20, 25, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

/* Goal Cards */
.goal-card {
  @apply h-full p-6 lg:p-8 rounded-2xl flex flex-col transition-all cursor-pointer;
  background: rgba(20, 20, 25, 0.9);
  border: 2px solid rgba(255, 255, 255, 0.08);
}

.goal-card:hover {
  transform: translateY(-4px);
}

.goal-card.lose-weight:hover {
  border-color: rgba(249, 115, 22, 0.5);
  box-shadow: 0 0 40px rgba(249, 115, 22, 0.15);
}

.goal-card.gain-weight:hover {
  border-color: rgba(34, 197, 94, 0.5);
  box-shadow: 0 0 40px rgba(34, 197, 94, 0.15);
}

/* Scrollbar Styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.25);
}

/* Custom Animations */
@keyframes pulse-slow {
  0%, 100% { opacity: 0.4; transform: scale(1); }
  50% { opacity: 0.7; transform: scale(1.05); }
}

@keyframes pulse-slower {
  0%, 100% { opacity: 0.3; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.08); }
}

@keyframes float {
  0%, 100% { transform: translateY(0) translateX(0); }
  25% { transform: translateY(-20px) translateX(10px); }
  50% { transform: translateY(-10px) translateX(-5px); }
  75% { transform: translateY(-25px) translateX(5px); }
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes gradient-shift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

@keyframes glow-pulse {
  0%, 100% { box-shadow: 0 0 20px rgba(168, 85, 247, 0.3); }
  50% { box-shadow: 0 0 40px rgba(168, 85, 247, 0.6); }
}

@keyframes border-glow {
  0%, 100% { border-color: rgba(168, 85, 247, 0.3); }
  50% { border-color: rgba(168, 85, 247, 0.7); }
}

.animate-pulse-slow {
  animation: pulse-slow 8s ease-in-out infinite;
}

.animate-pulse-slower {
  animation: pulse-slower 12s ease-in-out infinite;
}

.animate-float {
  animation: float 15s ease-in-out infinite;
}

.animate-shimmer {
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.1) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  background-size: 200% 100%;
  animation: shimmer 2s infinite;
}

.animate-gradient {
  background-size: 200% 200%;
  animation: gradient-shift 4s ease infinite;
}

.animate-glow-pulse {
  animation: glow-pulse 3s ease-in-out infinite;
}

.animate-border-glow {
  animation: border-glow 2s ease-in-out infinite;
}

/* Enhanced Button with Shimmer */
.btn-shimmer {
  position: relative;
  overflow: hidden;
}

.btn-shimmer::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.2),
    transparent
  );
  transition: left 0.5s ease;
}

.btn-shimmer:hover::after {
  left: 100%;
}

/* Enhanced Card with Animated Border */
.card-animated {
  position: relative;
  background: rgba(15, 15, 20, 0.8);
  border-radius: 1rem;
  overflow: hidden;
}

.card-animated::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    135deg,
    rgba(168, 85, 247, 0.4),
    rgba(99, 102, 241, 0.2),
    rgba(168, 85, 247, 0.1),
    rgba(99, 102, 241, 0.4)
  );
  background-size: 300% 300%;
  animation: gradient-shift 6s ease infinite;
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

.card-animated:hover::before {
  animation: gradient-shift 2s ease infinite;
}

/* Radial Gradient Background */
.bg-gradient-radial {
  background: radial-gradient(circle at center, var(--tw-gradient-from), var(--tw-gradient-to));
}

/* Text Gradient Animation */
.text-gradient-animated {
  background: linear-gradient(
    90deg,
    #a855f7,
    #6366f1,
    #8b5cf6,
    #a855f7
  );
  background-size: 300% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradient-shift 4s ease infinite;
}

/* Subtle noise texture overlay */
.noise-overlay {
  position: relative;
}

.noise-overlay::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 400 400' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
  opacity: 0.03;
  pointer-events: none;
}

/* Enhanced hover effects for interactive elements */
.interactive-card {
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}

.interactive-card:hover {
  transform: translateY(-4px) scale(1.01);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3), 0 0 30px rgba(168, 85, 247, 0.15);
}

/* Floating animation for badges */
@keyframes float-subtle {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

.animate-float-subtle {
  animation: float-subtle 3s ease-in-out infinite;
}

/* Breathing glow effect for CTA buttons */
@keyframes breathing-glow {
  0%, 100% { 
    box-shadow: 0 0 20px rgba(168, 85, 247, 0.3), 0 4px 15px rgba(168, 85, 247, 0.2);
  }
  50% { 
    box-shadow: 0 0 35px rgba(168, 85, 247, 0.5), 0 4px 25px rgba(168, 85, 247, 0.35);
  }
}

.animate-breathing-glow {
  animation: breathing-glow 2.5s ease-in-out infinite;
}

/* Sparkle effect */
@keyframes sparkle {
  0%, 100% { opacity: 0; transform: scale(0) rotate(0deg); }
  50% { opacity: 1; transform: scale(1) rotate(180deg); }
}

.sparkle-effect::before,
.sparkle-effect::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: white;
  border-radius: 50%;
  animation: sparkle 2s ease-in-out infinite;
}

.sparkle-effect::before {
  top: 10%;
  right: 15%;
  animation-delay: 0s;
}

.sparkle-effect::after {
  bottom: 15%;
  left: 10%;
  animation-delay: 1s;
}

/* Icon bounce on hover */
@keyframes icon-bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

.icon-hover-bounce:hover svg {
  animation: icon-bounce 0.4s ease-in-out;
}

/* Smooth underline effect */
.hover-underline {
  position: relative;
}

.hover-underline::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: linear-gradient(90deg, #a855f7, #6366f1);
  transition: width 0.3s ease;
}

.hover-underline:hover::after {
  width: 100%;
}

/* Enhanced focus ring */
.focus-ring-purple:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px rgba(15, 15, 20, 1), 0 0 0 4px rgba(168, 85, 247, 0.5);
}

/* Ripple effect on click */
@keyframes ripple {
  0% { transform: scale(0); opacity: 0.5; }
  100% { transform: scale(4); opacity: 0; }
}

.ripple-effect {
  position: relative;
  overflow: hidden;
}

.ripple-effect::after {
  content: '';
  position: absolute;
  width: 100%;
  height: 100%;
  top: 50%;
  left: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgba(255,255,255,0.2) 0%, transparent 60%);
  transform: translate(-50%, -50%) scale(0);
  opacity: 0;
}

.ripple-effect:active::after {
  animation: ripple 0.6s ease-out;
}

/* Subtle text shadow for headings */
.text-glow {
  text-shadow: 0 0 30px rgba(168, 85, 247, 0.3);
}

/* Enhanced stat number animation */
@keyframes count-up-glow {
  0% { text-shadow: 0 0 0 transparent; }
  50% { text-shadow: 0 0 20px currentColor; }
  100% { text-shadow: 0 0 0 transparent; }
}

.stat-number-glow {
  animation: count-up-glow 2s ease-out;
}

/**
 * Using the elevate system.
 * Automatic contrast adjustment.
 *
 * <element className="hover-elevate" />
 * <element className="active-elevate-2" />
 *
 * // Using the tailwind utility when a data attribute is "on"
 * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
 * // Or manually controlling the toggle state
 * <element className="toggle-elevate toggle-elevated" />
 *
 * Elevation systems have to handle many states.
 * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
 * - toggled or not
 * - focused or not (this is not handled with these utilities)
 *
 * Even without handling focused or not, this is six possible combinations that
 * need to be distinguished from eachother visually.
 */
@layer utilities {

  /* Hide ugly search cancel button in Chrome until we can style it properly */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder styling for contentEditable div */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
   * buttons/badges can remove the automatic brightness adjustment on interactions
   * and program their own. */
  .no-default-hover-elevate {}

  .no-default-active-elevate {}


  /**
   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
   * This way they can stack/compound. Both will overlap the parent's borders!
   * So borders will be automatically adjusted both on toggle, and hover/active,
   * and they will be compounded.
   */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: -1;
    /* sits behind content but above backdrop */
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Does not work on elements with overflow:hidden! */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: 999;
    /* sits in front of content */
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
    inset: -1px;
  }
}

import * as React from "react"
import * as TogglePrimitive from "@radix-ui/react-toggle"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const toggleVariants = cva(
  "inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 gap-2",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline:
          "border border-input bg-transparent hover:bg-accent hover:text-accent-foreground",
      },
      size: {
        default: "h-10 px-3 min-w-10",
        sm: "h-9 px-2.5 min-w-9",
        lg: "h-11 px-5 min-w-11",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

const Toggle = React.forwardRef<
  React.ElementRef<typeof TogglePrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof TogglePrimitive.Root> &
    VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive.Root
    ref={ref}
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
))

Toggle.displayName = TogglePrimitive.Root.displayName

export { Toggle, toggleVariants }

